begin
  if (select count(*) from public.worlds_meta_options where event_id = '2026-vgc-champion-team') <> 235
     or (select count(distinct option_key) from public.worlds_meta_options where event_id = '2026-vgc-champion-team') <> 235
     or (select count(distinct source_order) from public.worlds_meta_options where event_id = '2026-vgc-champion-team') <> 235
     or (select count(*) from public.worlds_meta_options where event_id = '2026-vgc-champion-team' and is_selectable) <> 235 then
    raise exception 'The official Regulation M-B pool must contain exactly 235 unique selectable options.';
  end if;

  if exists (
    select 1 from public.worlds_meta_options
    where event_id = '2026-vgc-champion-team'
      and (source_url <> 'https://web-view.app.pokemonchampions.jp/battle/pages/events/rs178066986988lmoqpm/en/pokemon.html' or source_checked_at <> '2026-08-11'::date)
  ) then
    raise exception 'Every VGC Meta Picks option must retain the reviewed official source and check date.';
  end if;

  if (select count(*) from public.worlds_meta_options where event_id = '2026-vgc-champion-team' and metadata ? 'community_trend_rank') <> 24 then
    raise exception 'The bounded community Trending cohort must contain exactly 24 official options.';
  end if;
end;
$verify_pool$;

